# Row padding verified; check the range of widths, which stops before len(S)
import math

s, t = input().split()
s, t = s.strip(), t.strip()

for w in range(1, len(s)):
    ss = [s[w*i:w*i+w] for i in range(math.ceil(len(s)/w))]
    if len(ss[-1]) < w:
        ss[-1] += " " * (w - len(ss[-1]))
    x = [*zip(*ss)]
    if len(x) >= len(t):
        for n in x[:len(t)]:
            if t == "".join(n).replace(" ", ""):
                print("Yes")
